Rules.InvariantScript:
If ( 
    varViewPaneDetails,

    Set(varViewPaneDetails, false),

    Set(varViewPaneDetails, true)

);

If ( 
    varViewPaneDetails,

    Set(varViewPaneDetails, false),

    Set(varViewPaneDetails, true)

);

//Set(varViewPaneDetails, true);
Set(varSelectedItem, dgrDatagrid.Selected);

Set(
    varInventoryDynamic,
    ParseJSON(
        JSON(
            LookUp(
                nfInventory As resource,
                resource.id = dgrDatagrid.Selected.id
            ),
            JSONFormat.Compact
        )
    )
);

If( 

    !varViewPaneDetails, 

    Navigate('Screen Form');

);

ControlPropertyState.AutoRuleBindingString:
Set(varViewPaneDetails, true);
Set(varSelectedItem, dgrDatagrid.Selected);

ClearCollect( 
    colSelectedItemDetails,
    {
        type: "env",
        displayName: "Environment Name",
        Value: varSelectedItem.environmentName,
        isLink: true, 
        link: "https://environmentlink"
    },
    {
        type: "env",
        displayName: "Environment Region",
        Value: varSelectedItem.environmentRegion,
        isLink: false
    },
    {
        type: "flow",
        displayName: "Display Name",
        Value: varSelectedItem.properties.displayName, 
        isLink: false
    },
    {
        type: "flow",
        displayName: "State",
        Value: varSelectedItem.properties.state, 
        isLink: false
    },  
    {
        type: "flow",
        displayName: "Trigger Type",
        Value: varSelectedItem.properties.triggerType,
        isLink: false
    }  

);

Rules.InvariantScript:
If(
    IsBlank(varInventoryDynamic),
    Blank(),
    Text(
        Column(
            varInventoryDynamic,
            ThisItem.column
        )
    )
)

If(
    IsBlank(varInventoryDynamic),
    Blank(),
    Text(
        Column(
            varInventoryDynamic,
            ThisItem.column
        )
    )
)

Set(varQbReady, false);
Patch(
    colInventoryFilter,
    ThisItem,
    {
        value: If(
            IsBlank(Self.SelectedDate),
            "",
            Text(Self.SelectedDate, "yyyy-mm-dd", "en-US")
        )
    }
)

Patch(  
    colInventoryFilter,
    ThisItem,
    {
        field: Self.Selected
    }
);

Reset(cmbFilterRowOperator);

Collect(
    colInventoryFilter, 
    {
        id: GUID(),
        enabled: true
    }
)

Set(varQbReady, false);
Set(varQbKql, Blank());
Set(varQbClausesJson, Blank());
Set(varQbTransportJson, Blank());
Set(varQbSnapshot, Blank());
Set(varQbToday, Today());

Set(
    varQbRules,
    IfError(
        ForAll(
            Filter(colInventoryFilter, enabled) As f,
            With(
                {
                    fld: LookUp(colInventoryColumns As c, c.FieldName = f.field.FieldName),
                    op: LookUp(colInventoryOperators As o, o.Operator = f.operator.Operator),
                    parsedDate: IfError(DateValue(f.value, "en-US"), Blank())
                },
                {
                    Id: f.id,
                    FieldName: fld.FieldName,
                    FieldType: fld.FieldType,
                    Operator: op.Operator,
                    QueryOperator: op.QueryOperator,
                    RawValue: f.value,
                    Day: If(
                        fld.FieldType = "DateTime",
                        Switch(
                            op.Operator,
                            "Yesterday", DateAdd(varQbToday, -1, TimeUnit.Days),
                            "Today", varQbToday,
                            "Tomorrow", DateAdd(varQbToday, 1, TimeUnit.Days),
                            parsedDate
                        ),
                        Blank()
                    ),
                    Valid:
                        !IsBlank(fld.FieldName) &&
                        !IsBlank(op.Operator) &&
                        (fld.FieldType in op.FieldTypes) &&
                        If(
                            fld.FieldType = "DateTime",
                            (op.Operator in ["On", "OnOrAfter", "OnOrBefore", "Yesterday", "Today", "Tomorrow"]) &&
                            (
                                (op.Operator in ["Yesterday", "Today", "Tomorrow"]) ||
                                (
                                    !IsBlank(parsedDate) &&
                                    Text(parsedDate, "yyyy-mm-dd", "en-US") = f.value
                                )
                            ),
                            (fld.FieldType in ["String", "LookUp"]) &&
                            !IsBlank(Trim(f.value)) &&
                            !IsMatch(f.value, "[\x00-\x08\x0B\x0C\x0E-\x1F]", MatchOptions.Contains) &&
                            (op.QueryOperator in ["==", "!=", "contains", "!contains", "startswith", "!startswith", "endswith", "!endswith"])
                        )
                }
            )
        ),
        Notify("Filterregels verwerken mislukt: " & FirstError.Message, NotificationType.Error);
        Blank()
    )
);

If(
    IsBlank(varQbRules),
    false,
    IsEmpty(varQbRules),
    Notify("Voeg ten minste één actief filter toe.", NotificationType.Error);
    false,
    !IsEmpty(Filter(varQbRules, !Valid)),
    Notify("Controleer veld, operator en waarde van de actieve filters.", NotificationType.Error);
    false,

    Set(
        varQbExtends,
        IfError(
            ForAll(
                Filter(
                    colInventoryColumns As column,
                    !IsBlank(column.ExtendExpression) &&
                    !IsBlank(LookUp(varQbRules As r, r.FieldName = column.FieldName))
                ) As selectedColumn,
                {
                    FieldName: selectedColumn.FieldName,
                    Expression: selectedColumn.ExtendExpression
                }
            ),
            Notify("Veldexpressies verwerken mislukt: " & FirstError.Message, NotificationType.Error);
            Blank()
        )
    );
    If(
        !IsBlank(varQbExtends),
        Set(
            varQbInitOk,
            IfError(
                ClearCollect(
                    colQbTerms,
                    Filter(
                        Table({ FieldName: "", QueryOperator: "", ValueType: "", RawValue: "", KqlLiteral: "" }),
                        false
                    )
                ),
                Notify("Queryvoorwaarden initialiseren mislukt: " & FirstError.Message, NotificationType.Error);
                false,
                true
            )
        );
        If(
            varQbInitOk,
            Set(
                varQbTermsOk,
                IfError(
                    ForAll(
                        varQbRules As r,
                        If(
                            r.FieldType = "DateTime",
                            With(
                                {
                                    d0: r.Day,
                                    d1: DateAdd(r.Day, 1, TimeUnit.Days)
                                },
                                With(
                                    {
                                        t0: Text(d0, DateTimeFormat.UTC),
                                        t1: Text(d1, DateTimeFormat.UTC)
                                    },
                                    Switch(
                                        r.Operator,
                                        "OnOrAfter",
                                        Collect(colQbTerms, {
                                            FieldName: r.FieldName, QueryOperator: ">=",
                                            ValueType: "DateTime", RawValue: t0,
                                            KqlLiteral: "datetime(" & t0 & ")"
                                        }),
                                        "OnOrBefore",
                                        Collect(colQbTerms, {
                                            FieldName: r.FieldName, QueryOperator: "<",
                                            ValueType: "DateTime", RawValue: t1,
                                            KqlLiteral: "datetime(" & t1 & ")"
                                        }),
                                        Collect(
                                            colQbTerms,
                                            {
                                                FieldName: r.FieldName, QueryOperator: ">=",
                                                ValueType: "DateTime", RawValue: t0,
                                                KqlLiteral: "datetime(" & t0 & ")"
                                            },
                                            {
                                                FieldName: r.FieldName, QueryOperator: "<",
                                                ValueType: "DateTime", RawValue: t1,
                                                KqlLiteral: "datetime(" & t1 & ")"
                                            }
                                        )
                                    )
                                )
                            ),
                            With(
                                { encoded: JSON(r.RawValue, JSONFormat.Compact) },
                                Collect(
                                    colQbTerms,
                                    {
                                        FieldName: r.FieldName,
                                        QueryOperator: r.QueryOperator,
                                        ValueType: "String",
                                        RawValue: r.RawValue,
                                        KqlLiteral:
                                            Char(39) &
                                            Substitute(
                                                Substitute(
                                                    Mid(encoded, 2, Len(encoded) - 2),
                                                    Char(92) & Char(34),
                                                    Char(34)
                                                ),
                                                Char(39),
                                                Char(92) & Char(39)
                                            ) &
                                            Char(39)
                                    }
                                )
                            )
                        )
                    ),
                    Notify("Queryvoorwaarden bouwen mislukt: " & FirstError.Message, NotificationType.Error);
                    false,
                    true
                )
            );
            If(
                varQbTermsOk,
                If(
                    IsEmpty(colQbTerms),
                    Notify("Er zijn geen queryvoorwaarden gemaakt.", NotificationType.Error),

                    Set(
                        varQbKql,
                        IfError(
                            "PowerPlatformResources" &
                            Char(10) &
                            "| where type == '" & varResourceType & "'" &
                            Concat(
                                varQbExtends As e,
                                Char(10) &
                                "| extend " & e.FieldName & " = " & e.Expression
                            ) &
                            Concat(
                                colQbTerms As t,
                                Char(10) &
                                "| where " & t.FieldName & " " &
                                t.QueryOperator & " " & t.KqlLiteral
                            ),
                            Notify(
                                "KQL bouwen mislukt: " & FirstError.Message,
                                NotificationType.Error
                            );
                            Blank()
                        )
                    );

                    Set(
                        varQbClausesJson,
                        IfError(
                            "[" &
                            JSON(
                                {
                                    '$type': "where",
                                    FieldName: "type",
                                    Operator: "==",
                                    Values: ["'microsoft.powerautomate/cloudflows'"]
                                },
                                JSONFormat.FlattenValueTables
                            ) &
                            Concat(
                                varQbExtends As e,
                                "," &
                                JSON(
                                    {
                                        '$type': "extend",
                                        FieldName: e.FieldName,
                                        Expression: e.Expression
                                    },
                                    JSONFormat.Compact
                                )
                            ) &
                            Concat(
                                colQbTerms As t,
                                "," &
                                JSON(
                                    {
                                        '$type': "where",
                                        FieldName: t.FieldName,
                                        Operator: t.QueryOperator,
                                        Values: [t.KqlLiteral]
                                    },
                                    JSONFormat.FlattenValueTables
                                )
                            ) &
                            "]",
                            Notify(
                                "Clauses maken mislukt: " & FirstError.Message,
                                NotificationType.Error
                            );
                            Blank()
                        )
                    );

                    Set(
                        varQbTransportJson,
                        IfError(
                            "[" &
                            JSON(
                                {
                                    FieldName: "type",
                                    Operator: "==",
                                    ValueType: "String",
                                    Value: "microsoft.powerautomate/cloudflows"
                                },
                                JSONFormat.Compact
                            ) &
                            Concat(
                                colQbTerms As t,
                                "," &
                                JSON(
                                    {
                                        FieldName: t.FieldName,
                                        Operator: t.QueryOperator,
                                        ValueType: t.ValueType,
                                        Value: t.RawValue
                                    },
                                    JSONFormat.Compact
                                )
                            ) &
                            "]",
                            Notify(
                                "Flow-invoer maken mislukt: " & FirstError.Message,
                                NotificationType.Error
                            );
                            Blank()
                        )
                    );

                    Set(
                        varQbSnapshot,
                        IfError(
                            JSON(
                                ForAll(
                                    colInventoryFilter As f,
                                    {
                                        Id: Text(f.id),
                                        FieldName: f.field.FieldName,
                                        Operator: f.operator.Operator,
                                        Value: f.value,
                                        Enabled: f.enabled
                                    }
                                ),
                                JSONFormat.Compact
                            ),
                            Notify("Filterstatus bewaren mislukt: " & FirstError.Message, NotificationType.Error);
                            Blank()
                        )
                    );
                    
                    Set(
                        varQbReady,
                        !IsBlank(varQbKql) &&
                        !IsBlank(varQbClausesJson) &&
                        !IsBlank(varQbTransportJson) &&
                        !IsBlank(varQbSnapshot)
                    );
                    If(
                        !varQbReady,
                        Set(varQbKql, Blank());
                        Set(varQbClausesJson, Blank());
                        Set(varQbTransportJson, Blank())
                    )
                )
            )
        )
    )
);



// Run flow!

Set(
    varQbCurrentSnapshot,
    IfError(
        JSON(
            ForAll(
                colInventoryFilter As f,
                {
                    Id: Text(f.id),
                    FieldName: f.field.FieldName,
                    Operator: f.operator.Operator,
                    Value: f.value,
                    Enabled: f.enabled
                }
            ),
            JSONFormat.Compact
        ),
        Notify("Filterstatus controleren mislukt: " & FirstError.Message, NotificationType.Error);
        Blank()
    )
);
If(
    IsBlank(varQbCurrentSnapshot),
    false,
    !varQbReady || varQbCurrentSnapshot <> varQbSnapshot || varQbToday <> Today(),
    Set(varQbReady, false);
    Notify("De filters of kalenderdag zijn gewijzigd. Bouw de query opnieuw.", NotificationType.Error),

    Set(varQbFlowFailed, false);
    Set(
        varQbFlowResult,
        IfError(

            Set(
                varInventory,
                ParseInventory(
                    'PPAT-SearchInventory'.Run(varQbClausesJson).data
                )
            ),

            Set(varQbFlowFailed, true);
            Notify("Flow aanroepen mislukt: " & FirstError.Message, NotificationType.Error);
            Blank()
        )
    );

)
